<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Snake Game</title>
    <style>
        body {
            background-color: #121212;
            color: #e0e0e0;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            overflow: hidden;
        }

        #score {
            font-size: 2rem;
            margin-bottom: 10px;
        }

        #snake {
            border: 4px solid #333;
            background-color: #000;
            box-shadow: 0 0 20px rgba(0, 0, 0, 0.5);
            image-rendering: pixelated;
        }

        .controls {
            margin-top: 20px;
            display: flex;
            gap: 10px;
        }

        button {
            padding: 10px 20px;
            font-size: 1rem;
            cursor: pointer;
            background-color: #4CAF50;
            border: none;
            color: white;
            border-radius: 4px;
            transition: background 0.2s;
        }

        button:hover {
            background-color: #45a049;
        }

        button:active {
            transform: translateY(1px);
        }

        #pause-btn {
            background-color: #ff9800;
        }

        #pause-btn:hover {
            background-color: #e68a00;
        }

        #reset-btn {
            background-color: #f44336;
        }

        #reset-btn:hover {
            background-color: #da190b;
        }
    </style>
</head>
<body>

    <div id="score">Score: 0</div>
    <canvas id="snake" width="400" height="400"></canvas>

    <div class="controls">
        <button id="start">Start</button>
        <button id="pause">Pause</button>
        <button id="reset">Reset</button>
    </div>

    <script>
        const canvas = document.getElementById('snake');
        const ctx = canvas.getContext('2d');
        const scoreEl = document.getElementById('score');

        let gameInterval = null;

        // Configuration
        const w = 20; // Grid columns
        const h = 20; // Grid rows
        const cellSize = canvas.width / w;

        window.game = {
            w: w,
            h: h,
            snake: [],      // Array of [x, y], Head first
            food: [0, 0],
            dir: 'right',   // Current heading
            nextDir: 'right', // Queued direction for next tick
            score: 0,
            alive: true,

            reset() {
                this.snake = [[5, 5], [4, 5], [3, 5]];
                this.food = [10, 10];
                this.dir = 'right';
                this.nextDir = 'right';
                this.score = 0;
                this.alive = true;
                updateUI();
                draw();
            },

            tick() {
                if (!this.alive) return;

                // Transition queued direction to active direction
                this.dir = this.nextDir;

                const head = this.snake[0];
                let newHead;

                // Calculate next position based on current heading
                if (this.dir === 'up') {
                    newHead = [head[0], head[1] - 1];
                } else if (this.dir === 'down') {
                    newHead = [head[0], head[1] + 1];
                } else if (this.dir === 'left') {
                    newHead = [head[0] - 1, head[1]];
                } else if (this.dir === 'right') {
                    newHead = [head[0] + 1, head[1]];
                }

                // Check Wall Collision
                if (newHead[0] < 0 || newHead[0] >= this.w || newHead[1] < 0 || newHead[1] >= this.h) {
                    this.alive = false;
                } else {
                    // Check Self-Collision
                    for (let i = 0; i < this.snake.length; i++) {
                        if (newHead[0] === this.snake[i][0] && newHead[1] === this.snake[i][1]) {
                            this.alive = false;
                            break;
                        }
                    }
                }

                if (this.alive) {
                    // Check Food Collision
                    if (newHead[0] === this.food[0] && newHead[1] === this.food[1]) {
                        this.score++;
                        this.snake.unshift(newHead); // Grow snake: add head, don't remove tail
                        this.generateFood();
                    } else {
                        this.snake.unshift(newHead); // New head
                        this.snake.pop();            // Remove tail
                    }
                }

                updateUI();
                draw();
            },

            setDir(d) {
                const opposites = { 'up': 'down', 'down': 'up', 'left': 'right', 'right': 'left' };
                // Ignore 180 degree reversals
                if (d !== opposites[this.dir]) {
                    this.nextDir = d;
                }
            },

            setFood(x, y) {
                this.food = [x, y];
                draw();
            },

            generateFood() {
                let valid = false;
                while (!valid) {
                    const newFood = [Math.floor(Math.random() * this.w), Math.floor(Math.random() * this.h)];
                    // Ensure food is not on snake body
                    const onSnake = this.snake.some(seg => seg[0] === newFood[0] && seg[1] === newFood[1]);
                    if (!onSnake) {
                        this.food = newFood;
                        valid = true;
                    }
                }
            },

            // API Getters for Grading
            snake() { return this.snake; },
            food() { return this.food; },
            alive() { return this.alive; },
            score() { return this.score; }
        };

        function updateUI() {
            scoreEl.innerText = `Score: ${game.score()}`;
            if (!game.alive) {
                scoreEl.innerText += " - GAME OVER";
            }
        }

        function draw() {
            // Clear Canvas
            ctx.fillStyle = '#000';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw Food
            ctx.fillStyle = '#F44336';
            const [fx, fy] = game.food;
            ctx.fillRect(fx * cellSize + 2, fy * cellSize + 2, cellSize - 4, cellSize - 4);

            // Draw Snake
            game.snake.forEach((seg, index) => {
                ctx.fillStyle = (index === 0) ? '#8BC34A' : '#4CAF50'; // Head is brighter
                ctx.fillRect(seg[0] * cellSize + 2, seg[1] * cellSize + 2, cellSize - 4, cellSize - 4);
            });
        }

        // Input Handling
        window.addEventListener('keydown', (e) => {
            switch(e.key) {
                case 'ArrowUp': game.setDir('up'); break;
                case 'ArrowDown': game.setDir('down'); break;
                case 'ArrowLeft': game.setDir('left'); break;
                case 'ArrowRight': game.setDir('right'); break;
            }
        });

        // Button Logic
        document.getElementById('start').addEventListener('click', () => {
            if (!gameInterval) {
                gameInterval = setInterval(() => game.tick(), 100); // 10 ticks per second
            }
        });

        document.getElementById('pause').addEventListener('click', () => {
            clearInterval(gameInterval);
            gameInterval = null;
        });

        document.getElementById('reset').addEventListener('click', () => {
            clearInterval(gameInterval);
            gameInterval = null;
            game.reset();
        });

        // Initialize Game State
        game.reset();
    </script>
</body>
</html>
